select mn.*,
       pp.p_name projectName,
       cc.con_name contractName,
       pp.p_code projectCode,
        pp.p_region projectRegion,
        pp.p_longitude projectLongitude,
        pp.p_latitude projectLatitude,
        pp.p_overview projectOverview,
        pp.p_construction_unit projectConstructionUnit,
        pp.p_approve_budget projectApproveBudget,
        pp.p_approve_budget_code projectApproveBudgetCode ,
        pp.p_approve_budget_date projectApproveBudgetDate ,
        pp.p_build_model projectBuildModel,
        pp.P_Project_Form_Type projectFormType ,
        pp.P_Project_Number projectNumber ,
        pp.p_approval_investment_amount approvalInvestmentAmount ,
        pp.p_can_yan_apply_unit canYanApplyUnit ,
        pp.p_can_yan_approval_unit canYanApprovalUnit ,
        pp.p_record_num recordNum ,
        pp.p_record_date recordDate ,
        pp.p_record_amount recordAmount ,
        pp.p_legal_unit projectLegalUnit ,
        pp.p_record_issue_unit recordIssueUnit ,
        pp.p_apply_date projectApplyDate ,
        pp.p_build_year projectBuildYear ,
        pp.p_approval_amount projectApprovalAmount,
        pp.p_build_type projectBuildType,
        pp.p_professional_type projectProfessionalType,
        pp.p_transfer_unit projectProfessionalType,
        pp.p_project_manager projectProjectManager,
        pp.p_project_leader projectProjectLeader,
        pp.p_department projectDepartment,
        pp.p_engineer projectEngineer,
        pp.p_engineer_leader projectEngineerLeader
from full_process_consult_service_protocol_meterage_apply mn
left join pre_project pp on pp.p_id = mn.project_id
left join con_contract cc on cc.con_id = mn.contract_id
where 1 = 1

    
        
            and likePname(#{request.projectName},pp.P_Id)=true
        
        
            and pp.p_name like concat('%',#{request.projectName},'%')
        
    


    and cc.con_name like concat('%',#{request.contractName},'%')


    and pp.p_name in
    #{item}


    and cc.con_name in
    #{item}


    and pp.p_id in
    #{item}


    and pp.P_Code  in
    
        #{item}
    


    and pp.P_Region like concat('%',#{request.projectRegion},'%')


    and pp.P_Longitude =#{request.pLongitude}


    and pp.P_Latitude =#{request.pLatitude}


    and pp.P_Overview in
    
        #{item}
    


    and pp.P_Construction_Unit = #{request.projectConstructionUnit}


    and pp.P_Approve_Budget in
    
        #{item}
    


    and pp.P_Approve_Budget_Code in
    
        #{item}
    


    and pp.P_Approve_Budget_Date = #{request.projectApproveBudgetDate}


    and mn.create_uname in
    
        #{item}
    


    and mn.create_time = #{request.createTime}


    and mn.state in
    
        #{item}
    


    and pp.P_Build_Model in
    
        #{item}
    


    and pp.P_Project_Form_Type in
    
        #{item}
    


    and pp.P_Project_Number in
    
        #{item}
    


    and pp.P_Approval_Investment_Amount in
    
        #{item}
    


    and pp.P_Can_Yan_Apply_Unit in
    
        #{item}
    


    and pp.P_Can_Yan_Approval_Unit in
    
        #{item}
    


    and pp.P_Record_Num in
    
        #{item}
    


    and pp.P_Record_Date = #{request.recordDate}


    and pp.P_Record_Amount in
    
        #{item}
    


    and pp.P_Legal_Unit in
    
        #{item}
    


    and pp.P_Record_Issue_Unit in
    
        #{item}
    


    and pp.P_Apply_Date= #{request.projectApplyDate}


    and pp.P_Build_Year in
    
        #{item}
    


    and pp.P_Approval_Amount in
    
        #{item}
    


    and pp.P_Build_Type in
    
        #{item}
    


    and pp.P_Professional_Type in
    
        #{item}
    


    and pp.P_Transfer_Unit in
    
        #{item}
    


    and pp.P_Project_Manager in
    
        #{item}
    


    and pp.P_Project_Leader in
    
        #{item}
    


    and pp.P_Engineer in
    
        #{item}
    


    and pp.P_Engineer_Leader in
    
        #{item}
    


    and pp.P_Department= #{request.projectDepartment}


    and mn.contract_amount in
    
        #{item}
    


    and mn.this_stage_plan_pay_amount in
    
        #{item}
    


    and mn.should_pay_amount_total in
    
        #{item}
    


    and mn.total_pay_rate = #{request.totalPayRate}


    and (mn.create_uid = #{uId}
        or exists (select 1 from SYS_Task st where st.TaskEntityID = mn.id and (st.TaskUser = #{uId} or st.TaskSendUser = #{uId}))
        or exists (select 1 from Sys_Task_Processin sp where sp.tp_entityid = mn.id and (sp.tp_from = #{uId} or FIND_IN_SET(#{uId}, sp.tp_send)))
    )

order by mn.create_time desc

